import { SITE_URL } from "@/lib/site";

/** utm_medium used for every link generated by the share buttons. */
export const SHARE_MEDIUM = "partage";

export type ShareNetwork =
  | "whatsapp"
  | "facebook"
  | "x"
  | "linkedin"
  | "reddit"
  | "telegram"
  | "email"
  | "lien_copie"
  | "partage_mobile";

export const NETWORK_LABEL: Record<ShareNetwork, string> = {
  whatsapp: "WhatsApp",
  facebook: "Facebook",
  x: "X",
  linkedin: "LinkedIn",
  reddit: "Reddit",
  telegram: "Telegram",
  email: "E-mail",
  lien_copie: "Lien copié",
  partage_mobile: "Partage mobile",
};

export type ShareKind = "article" | "video";

/**
 * Absolute URL of the content with tracking parameters.
 * - utm_source  = network the link was shared on
 * - utm_medium  = "partage"
 * - utm_campaign = content slug (which content brought the visit)
 * - utm_content = content kind (article / video)
 */
export function buildTrackedUrl(path: string, network: ShareNetwork, campaign: string, kind: ShareKind): string {
  const clean = path.startsWith("/") ? path : `/${path}`;
  const u = new URL(clean, SITE_URL);
  u.searchParams.set("utm_source", network);
  u.searchParams.set("utm_medium", SHARE_MEDIUM);
  u.searchParams.set("utm_campaign", campaign);
  u.searchParams.set("utm_content", kind);
  return u.toString();
}

/** Link that opens the network's share screen for the given (tracked) URL. */
export function shareIntentUrl(network: ShareNetwork, trackedUrl: string, title: string): string | null {
  const e = encodeURIComponent;
  switch (network) {
    case "whatsapp":
      return `https://wa.me/?text=${e(`${title} ${trackedUrl}`)}`;
    case "facebook":
      return `https://www.facebook.com/sharer/sharer.php?u=${e(trackedUrl)}`;
    case "x":
      return `https://twitter.com/intent/tweet?text=${e(title)}&url=${e(trackedUrl)}`;
    case "linkedin":
      return `https://www.linkedin.com/sharing/share-offsite/?url=${e(trackedUrl)}`;
    case "reddit":
      return `https://www.reddit.com/submit?url=${e(trackedUrl)}&title=${e(title)}`;
    case "telegram":
      return `https://t.me/share/url?url=${e(trackedUrl)}&text=${e(title)}`;
    case "email":
      return `mailto:?subject=${e(title)}&body=${e(`${title}\n\n${trackedUrl}`)}`;
    default:
      return null;
  }
}

export type Utm = {
  utm_source: string;
  utm_medium: string | null;
  utm_campaign: string | null;
  utm_content: string | null;
};

/** Read tracking parameters from a query string ("?utm_source=..."). Null when no utm_source. */
export function readUtm(search: string): Utm | null {
  const p = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
  const clip = (v: string | null) => (v ? v.slice(0, 120) : null);
  const source = clip(p.get("utm_source"));
  if (!source) return null;
  return {
    utm_source: source,
    utm_medium: clip(p.get("utm_medium")),
    utm_campaign: clip(p.get("utm_campaign")),
    utm_content: clip(p.get("utm_content")),
  };
}
